const limiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 10, keyGenerator: (r) => `${r.ip}:${r.body?.email}` });

app.post("/login", limiter, async (req, res) => {
  const user = await db.user.findByEmail(req.body.email);
  const ok = user && (await argon2.verify(user.passwordHash, req.body.password));
  if (!ok) return res.status(401).json({ error: "wrong email or password" });   // mesma mensagem nos dois casos
  req.session.regenerate(() => {         // novo id após o login: derrota a fixation
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.use(session({ cookie: { httpOnly: true, secure: true, sameSite: "lax", maxAge: 3600_000 } }));

