def test_login_is_throttled(client):
    codes = [client.post("/login", json={"email": "a@x.io", "password": f"guess{i}"}).status_code for i in range(15)]
    assert 429 in codes

def test_session_id_changes_after_login(client, user):
    before = client.get("/").cookies.get("sid")
    client.post("/login", json=user.credentials)
    assert client.cookies.get("sid") != before

def test_unsigned_token_is_rejected(client):
    forged = b64(b'{"alg":"none"}') + "." + b64(b'{"sub":"admin"}') + "."
    assert client.get("/api/me", headers={"Authorization": f"Bearer {forged}"}).status_code == 401

def test_cookie_flags(client, user):
    cookie = client.post("/login", json=user.credentials).headers["set-cookie"]
    assert "HttpOnly" in cookie and "Secure" in cookie
